ALTER TABLE pricing_offers ENABLE ROW LEVEL SECURITY;
ALTER TABLE enterprise_quote_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON pricing_offers,enterprise_quote_requests FROM PUBLIC;
CREATE POLICY backend_only ON pricing_offers TO huddle_backend USING(TRUE) WITH CHECK(TRUE);
CREATE POLICY backend_only ON enterprise_quote_requests TO huddle_backend USING(TRUE) WITH CHECK(TRUE);
GRANT SELECT ON pricing_offers TO huddle_backend;
GRANT UPDATE(version,monthly_price_id,annual_price_id,quote_annual_seat_paise,minimum_seats,cards_per_seat) ON pricing_offers TO huddle_backend;
GRANT SELECT,INSERT ON enterprise_quote_requests TO huddle_backend;
